(function addCygnusKnights() {
    const JOB_META = {
        SoulMaster:  { zh: '聖魂劍士', face: 'emblems/soulmaster_face.webp' },
        FlameWizard: { zh: '烈焰巫師', face: 'emblems/flamewizard_face.webp' },
        WindBreaker: { zh: '破風使者', face: 'emblems/windbreaker_face.webp' },
        NightWalker: { zh: '暗夜行者', face: 'emblems/nightwalker_face.webp' },
        Striker:     { zh: '閃雷悍將', face: 'emblems/striker_face.webp' }
    };
    const TIER_LEVEL = { 1: 10, 2: 30, 3: 70, 4: 120 };
    const findExplorer = (name) => {
        for (const [jn, j] of Object.entries(allProfessionsData)) {
            if (j.group === '皇家騎士團') continue;
            for (const arr of Object.values(j.skills)) for (const s of arr) if (s.name === name) return s;
        }
        return null;
    };
    for (const [key, spec] of Object.entries(artaleCygnusSpec)) {
        const meta = JOB_META[key];
        const stageKeys = ['0轉 (新手)', '1轉', '2轉', '3轉', '4轉 (' + meta.zh + ')'];
        const job = {
            group: '皇家騎士團', isNew: true, cardImage: meta.face, emblemUrl: meta.face,
            startingLevelForSp: 10, jobAdvancementSpBonuses: [10, 30, 70, 120],
            jobStagesOrder: stageKeys.concat(['超技能', '5轉技能', '共通技能']),
            spRequiredFor2ndJob: 61, spRequiredFor3rdJob: 182, spRequiredFor4thJob: 333,
            skills: {}
        };
        job.jobStagesOrder.forEach(k => job.skills[k] = []);
        const idOf = {};
        spec.skills.forEach(sp => { idOf[sp.name] = 'c' + sp.pid; });
        for (const sp of spec.skills) {
            let maxLevel = sp.maxLevel, desc = sp.desc, fb = null;
            if (!maxLevel || !desc) { fb = findExplorer(sp.name); if (fb) { maxLevel = maxLevel || fb.maxLevel; desc = desc || fb.description; } }
            maxLevel = maxLevel || 1;
            const s = { id: 'c' + sp.pid, name: sp.name, maxLevel, requiredLevel: TIER_LEVEL[sp.tier], preRequisite: {}, description: desc || '', imageUrl: (window.__IMG && window.__IMG['images/c_' + sp.pid + '.png']) || ('images/c_' + sp.pid + '.png'), levels: [null], _cygnus: true };
            if (sp.pre) {
                let pid = idOf[sp.pre[0]];
                if (!pid) { const cands = Object.keys(idOf).filter(n => n.startsWith(sp.pre[0])); if (cands.length === 1) pid = idOf[cands[0]]; } // 官網前置名稱有時是簡稱（如「雷鳴」＝雷鳴衝擊）
                if (pid) s.preRequisite[pid] = sp.pre[1];
            }
            for (let i = 1; i <= maxLevel; i++) {
                const parts = sp.stats.map(([label, arr]) => arr[i - 1] !== undefined && arr[i - 1] !== '無' ? label + ': ' + arr[i - 1] : null).filter(Boolean);
                let effect = parts.join('，');
                if (!effect && fb && fb.levels && fb.levels[i]) effect = fb.levels[i].effect || '';
                s.levels.push({ effect, fullDescription: (desc ? desc.split('\n')[0] + ' ' : '') + (effect ? '等級' + i + '效果：' + effect + '。' : '') });
            }
            job.skills[stageKeys[sp.tier]].push(s);
        }
        allProfessionsData[meta.zh + ' (' + key + ')'] = job;
        recommendedBuilds[meta.zh + ' (' + key + ')'] = [];
    }
})();

// ===== 使用者提供的說明修正（全職業；放在最後載入的覆蓋檔，確保皇家騎士團也套用）=====
(function applyUserDescriptionFixes() {
    const MAPLE_PURIFY = '全職業的共通技能，能解除異常狀態，隨著等級提高，可解除的狀態會增加，等級越高冷卻越短。';
    for (const [jobName, job] of Object.entries(allProfessionsData)) {
        for (const arr of Object.values(job.skills)) for (const s of arr) {
            if (s.name === '楓葉淨化') s.description = MAPLE_PURIFY;                       // 使用者提供
            if (jobName === '黑騎士 (DarkKnight)' && s.name === '黑暗守護') {
                s.description = (s.description || '') + '\n11 級：增加一階的攻擊速度。';        // 使用者補充
            }
        }
    }
})();

// ===== 0 轉（新手）技能：來源＝使用者提供的遊戲內截圖。0 轉（1~10 級）只給 6 點，三個技能各最高 3 級（合計最多 9 點，只能點 6 點）=====
(function addBeginnerSkills() {
    const lv = (arr) => [null].concat(arr.map(e => ({ effect: e, fullDescription: '' })));
    const SNAIL = { id: 'b_snailThrow', name: '嫩寶丟擲術', maxLevel: 3, requiredLevel: 1, preRequisite: {}, imageUrl: 'images/b_snailThrow.png',
        description: '投擲蝸牛殼攻擊遠距離敵人。',
        levels: lv(['消耗MP: 3，傷害: 10', '消耗MP: 5，傷害: 25', '消耗MP: 7，傷害: 40']) };
    const NIMBLE = { id: 'b_nimbleFeet', name: '疾風之步', maxLevel: 3, requiredLevel: 1, preRequisite: {}, imageUrl: 'images/b_nimbleFeet.png',
        description: '瞬間內快速移動。\n再次使用等待時間：1分鐘',
        levels: lv(['消耗MP: 4，持續時間: 4秒，提升移動速度: 10', '消耗MP: 7，持續時間: 8秒，提升移動速度: 15', '消耗MP: 10，持續時間: 12秒，提升移動速度: 20']) };
    const recovery = (name) => ({ id: 'b_recovery', name, maxLevel: 3, requiredLevel: 1, preRequisite: {}, imageUrl: 'images/b_recovery.png',
        description: '在30秒內，持續恢復自身HP。\n再次使用等待時間：2分鐘',
        levels: lv(['消耗MP: 5，持續時間: 30秒，恢復HP: 24', '消耗MP: 10，持續時間: 30秒，恢復HP: 48', '消耗MP: 15，持續時間: 30秒，恢復HP: 72']) });
    const clone = (o) => JSON.parse(JSON.stringify(o));
    for (const [jobName, job] of Object.entries(allProfessionsData)) {
        const stage = job.jobStagesOrder[0];            // '0轉 (新手)'
        const noble = job.group === '皇家騎士團';
        // 冒險家：嫩寶丟擲術、疾風之步、恢復；皇家騎士團（貴族技術）：嫩寶丟擲術、恢復、疾風之步（使用者確認：兩邊都叫「恢復」，順序依遊戲內截圖）
        job.skills[stage] = noble ? [clone(SNAIL), recovery('恢復'), clone(NIMBLE)] : [clone(SNAIL), clone(NIMBLE), recovery('恢復')];
        job.beginnerSp = 6;                              // 0 轉（1~10 級）給 6 點技能點
    }
})();

// 互斥備註：皇家騎士團職業在這個檔案才建立，所以這裡再套用一次（artale-patch.js 的 artaleConflictNotes）
(function attachConflictNotesForCygnus() {
    for (const [jobName, bySkill] of Object.entries(artaleConflictNotes)) {
        const job = allProfessionsData[jobName]; if (!job) continue;
        for (const arr of Object.values(job.skills)) for (const s of arr) if (bySkill[s.name]) s.conflictNotes = bySkill[s.name];
    }
})();

// 特例：閃雷悍將 1~3 轉技能全點滿只有 330 點，低於 4 轉需求 333（Edward 說暫時維持，正式改版再確認）。
// 先給一顆「特例」按鈕，手動開啟後，4 轉需求改為「1~3 轉全部點滿」，讓剩下的技能點可以點 4 轉。
(function addStrikerSpecialCase() {
    const job = allProfessionsData['閃雷悍將 (Striker)'];
    if (job) job.specialCase = true;
})();

// ===== 皇家騎士團「等級效果」空白的補法（Edward 2026-11-18 指定）=====
// 1) 先用測試版（v2）冒險家資料裡「同名且最高等級相同」的技能；2) 正式版資料與 1) 的同名技能相同，沒有額外來源；
// 3) 同名技能在不同職業的效果不一致，或找不到的，不補（保持空白，列在待確認清單）。補上的技能會標 _effectFrom。
(function fillCygnusEffectsFromExplorers() {
    const PREF = { 'WindBreaker|替身術': 'Bowmaster', 'Striker|衝鋒': 'Buccaneer' };
    const royal = [], explorers = [];
    for (const [jn, j] of Object.entries(allProfessionsData)) {
        for (const arr of Object.values(j.skills)) for (const s of arr) (j.group === '皇家騎士團' ? royal : explorers).push([jn, s]);
    }
    const has = s => (s.levels || []).some(l => l && l.effect && l.effect.trim());
    const sigOf = s => JSON.stringify((s.levels || []).map(l => (l && l.effect) || ''));
    royal.forEach(([jn, s]) => {
        if (has(s)) return;
        let c = explorers.filter(([, e]) => e.name === s.name && e.maxLevel === s.maxLevel && has(e));
        if (c.length && new Set(c.map(([, e]) => sigOf(e))).size !== 1) {   // 同名技能在冒險家各職業數值不同：依 Edward 指定「用既有資料補」，改用同武器系的冒險家職業（弓→箭神、拳套→拳霸）
            const pref = PREF[jn.split(' (')[1].replace(')', '') + '|' + s.name];
            c = pref ? c.filter(([n]) => n.indexOf('(' + pref + ')') >= 0) : [];
        }
        if (!c.length) return;
        const src = c[0][1], desc = (s.description || '').split('\n')[0];
        s.levels = s.levels.map((l, i) => { if (i === 0) return null; const eff = (src.levels[i] && src.levels[i].effect) || ''; return { effect: eff, fullDescription: (desc ? desc + ' ' : '') + (eff ? '等級' + i + '效果：' + eff + '。' : '') }; });
        s._effectFrom = c.map(([n]) => n.split(' ')[0]).join('/');
    });
})();
